#!/usr/bin/env node
// src/data/ValidateTrivia.js
//
// Validates the generated trivia question files. Plain Node.js — no
// TypeScript, no extra deps. Sibling of ValidateCards.js.
//
//   node src/data/ValidateTrivia.js
//
// Exits with code 1 if any errors are found.
//
// These files are GENERATED by tools/convert-trivia.js — never hand-edit them.
// To remove a bad question, add its id to tools/blocklist.json and re-run the
// converter. This script exists to catch the things the converter can't:
// regressions from a hand-edit, a bad mapping change, or a fresh dump that
// quietly unbalances the wedges.

const fs = require('fs');
const path = require('path');

const TRIVIA_DIR = path.join(__dirname, 'trivia');

/** Keep in sync with tools/convert-trivia.js and src/data/trivia/types.ts. */
const WEDGES = ['geography', 'entertainment', 'history', 'arts', 'science', 'sport'];

/**
 * Below this, a wedge runs dry inside a single game and players start seeing
 * repeats. A warning, not an error — Phase 1 ships deliberately under it.
 */
const MIN_PER_WEDGE = 60;

const VALID_DIFFICULTY = new Set([1, 2, 3]);
const BOOLEAN_ANSWERS = new Set(['True', 'False']);

let errors = 0;
let warnings = 0;

function err(where, msg) {
  console.error(`  \u2717 [${where}]: ${msg}`);
  errors++;
}

function warn(where, msg) {
  console.warn(`  \u26a0  [${where}]: ${msg}`);
  warnings++;
}

const seenIds = new Map();    // id → "wedge #index"
const seenText = new Map();   // normalised question → "wedge #index"
const counts = {};

for (const wedge of WEDGES) {
  const filePath = path.join(TRIVIA_DIR, `${wedge}.json`);
  console.log(`\nChecking ${wedge}.json...`);

  if (!fs.existsSync(filePath)) {                                // nosemgrep -- dev-only CLI, hardcoded path
    err(wedge, `file not found: ${filePath} — run: node tools/convert-trivia.js`);
    continue;
  }

  let data;
  try {
    data = JSON.parse(fs.readFileSync(filePath, 'utf8'));         // nosemgrep -- dev-only CLI, hardcoded path
  } catch (e) {
    err(wedge, `JSON parse error — ${e.message}`);
    continue;
  }

  if (!Array.isArray(data)) {
    err(wedge, 'root value must be a JSON array');
    continue;
  }

  counts[wedge] = data.length;

  data.forEach((q, i) => {
    const where = `${wedge} #${i}`;

    if (!q || typeof q !== 'object') {
      err(where, 'question is not an object');
      return;
    }

    // ── Identity ──
    if (typeof q.id !== 'string' || !q.id.trim()) {
      err(where, 'missing or empty "id"');
    } else {
      if (!q.id.startsWith(`${wedge}-`)) {
        err(where, `id "${q.id}" does not start with its wedge prefix "${wedge}-"`);
      }
      const firstId = seenIds.get(q.id);
      if (firstId) err(where, `duplicate id "${q.id}" — already used at ${firstId}`);
      else seenIds.set(q.id, where);
    }

    if (q.wedge !== wedge) {
      err(where, `"wedge" is "${q.wedge}" but the question lives in ${wedge}.json`);
    }

    if (typeof q.sourceCategory !== 'string' || !q.sourceCategory.trim()) {
      err(where, 'missing "sourceCategory" — needed to re-map wedges later');
    }

    // ── Shape ──
    if (q.type !== 'multiple' && q.type !== 'boolean') {
      err(where, `"type" must be "multiple" or "boolean" (got ${JSON.stringify(q.type)})`);
    }

    if (!VALID_DIFFICULTY.has(q.difficulty)) {
      err(where, `"difficulty" must be 1, 2 or 3 (got ${JSON.stringify(q.difficulty)})`);
    }

    const question = typeof q.question === 'string' ? q.question : '';
    if (!question.trim()) err(where, 'missing or empty "question"');

    const answer = typeof q.answer === 'string' ? q.answer : '';
    if (!answer.trim()) err(where, 'missing or empty "answer"');

    if (!Array.isArray(q.distractors)) {
      err(where, '"distractors" must be an array');
    } else {
      const expected = q.type === 'boolean' ? 1 : 3;
      if (q.distractors.length !== expected) {
        err(where, `${q.type} question has ${q.distractors.length} distractor(s), expected ${expected}`);
      }
      if (q.distractors.some(d => typeof d !== 'string' || !d.trim())) {
        err(where, '"distractors" contains a non-string or empty entry');
      }

      // An answer duplicated in the distractors makes the question unanswerable.
      const lowerAnswer = answer.trim().toLowerCase();
      if (q.distractors.some(d => String(d).trim().toLowerCase() === lowerAnswer)) {
        err(where, `answer "${answer}" also appears in the distractors`);
      }

      const uniqueDistractors = new Set(q.distractors.map(d => String(d).trim().toLowerCase()));
      if (uniqueDistractors.size !== q.distractors.length) {
        err(where, 'duplicate entries in "distractors"');
      }
    }

    // ── Boolean questions must actually be True/False ──
    if (q.type === 'boolean') {
      if (!BOOLEAN_ANSWERS.has(answer)) {
        err(where, `boolean question answer must be "True" or "False" (got ${JSON.stringify(answer)})`);
      }
      const d0 = Array.isArray(q.distractors) ? q.distractors[0] : undefined;
      if (BOOLEAN_ANSWERS.has(answer) && d0 !== (answer === 'True' ? 'False' : 'True')) {
        err(where, `boolean distractor should be the opposite of "${answer}" (got ${JSON.stringify(d0)})`);
      }
    }

    // ── Undecoded HTML entities — the OpenTDB failure mode ──
    const fields = [question, answer, ...(Array.isArray(q.distractors) ? q.distractors : [])];
    for (const field of fields) {
      const entity = String(field).match(/&[a-zA-Z#][a-zA-Z0-9]*;/);
      if (entity) {
        err(where, `undecoded HTML entity "${entity[0]}" — re-run tools/convert-trivia.js`);
        break;
      }
    }

    // ── Duplicate question text across every wedge ──
    if (question.trim()) {
      const key = question.trim().replace(/\s+/g, ' ').toLowerCase();
      const first = seenText.get(key);
      if (first) warn(where, `duplicate question text — already defined at ${first}`);
      else seenText.set(key, where);
    }

    if (question.length > 220) {
      warn(where, `question is very long (${question.length} chars) — may overflow the card UI`);
    }
  });

  console.log(`  \u2192 ${data.length} question(s)`);
}

// ─────────────────────────────────────────────
// Balance — the failure mode of a random OpenTDB pull
// ─────────────────────────────────────────────

console.log('\nWedge balance:');
const present = WEDGES.filter(w => counts[w] !== undefined);
const max = Math.max(1, ...present.map(w => counts[w]));
for (const wedge of present) {
  const n = counts[wedge];
  const bar = '\u2588'.repeat(Math.round((n / max) * 32));
  console.log(`  ${wedge.padEnd(14)} ${String(n).padStart(4)}  ${bar}`);
}

for (const wedge of present) {
  if (counts[wedge] < MIN_PER_WEDGE) {
    warn('balance', `${wedge} has only ${counts[wedge]} question(s) — target is ${MIN_PER_WEDGE}+ before shipping`);
  }
}

const nonEmpty = present.filter(w => counts[w] > 0);
if (nonEmpty.length > 1) {
  const lo = Math.min(...nonEmpty.map(w => counts[w]));
  const hi = Math.max(...nonEmpty.map(w => counts[w]));
  if (hi / lo > 3) {
    warn('balance', `largest wedge has ${(hi / lo).toFixed(1)}x the questions of the smallest — fetch per-category to even this out`);
  }
}

// ─────────────────────────────────────────────
// Summary
// ─────────────────────────────────────────────

console.log('\n────────────────────────────────────────');
if (errors === 0 && warnings === 0) {
  console.log('\u2705  All trivia questions valid. No issues found.\n');
} else {
  if (warnings > 0) console.warn(`\u26a0   ${warnings} warning(s)`);
  if (errors > 0) console.error(`\u2717   ${errors} error(s) — fix before shipping\n`);
}
console.log('────────────────────────────────────────\n');

process.exit(errors > 0 ? 1 : 0);
